/*
 * sprites.js - every frame of Pip, as plain data. GENERATED - do not edit.
 *
 * Each frame is 64 strings of 64 characters. Every character is a palette
 * key from palettes.js and "." means transparent. Frames are drawn facing
 * right; the renderer flips them horizontally to face left.
 *
 * FRAME_META holds what the runtime needs to dress a frame up (compose.js):
 * where the eyes are and what was under them, the crown and ends a trait
 * hangs from, the body ellipse a pattern follows, and whether he is
 * wearing a hat.
 *
 * Generated by tools/gen-sprites.js from tools/frame-specs.js. At 64x64 the
 * shading is computed, not painted, so change the pose spec and run
 * "npm run sprites" rather than editing pixels here.
 */

